parameters.query:
SELECT id, pseudo, age, sexe, poids, taille, objectif, jours_disponibilite, materiel , date_fin, niveau
FROM fittracker.utilisateurs
WHERE id = {{ $json.body.user_id }}

parameters.jsCode:
let user = $('Récup Infos Utilisateur').first().json;
let exercices = $('Récup Liste Exercices').all().map(e => e.json);

if (!user.age || !user.poids || !user.taille || !user.jours_disponibilite || !user.date_fin) {
  throw new Error('Données utilisateur incomplètes : age, poids, taille, jours_disponibilite ou date_fin manquant');
}

let bmr = (user.sexe === 'Homme')
  ? (10 * user.poids) + (6.25 * user.taille) - (5 * user.age) + 5
  : (10 * user.poids) + (6.25 * user.taille) - (5 * user.age) - 161;

let tdee = bmr * 1.4;
let calObj = tdee;

switch (user.objectif) {
  case 'Perte de poids':             calObj = tdee * 0.80; break;
  case 'Prise de masse':             calObj = tdee * 1.15; break;
  case 'Restructuration corporelle': calObj = tdee * 0.95; break;
  default:                           calObj = tdee; break;
}

const now = new Date();
const jourSemaine = now.getDay();
const debutAnnee = new Date(now.getFullYear(), 0, 1);
const numSemaine = Math.ceil(((now - debutAnnee) / 86400000 + debutAnnee.getDay() + 1) / 7);

const phases = ['montee', 'pic', 'decharge'];
const phaseHebdo = phases[numSemaine % 3];

const jours = user.jours_disponibilite.split(',').length;
let splitSelectionne;
if (jours <= 2)       splitSelectionne = 'Full Body';
else if (jours === 3) splitSelectionne = 'Push / Pull / Legs';
else if (jours <= 5)  splitSelectionne = 'Upper / Lower';
else                  splitSelectionne = 'PPL 6 jours';

const listeExercicesDetails = exercices.map(e => `${e.nom} [${e.muscles}] (${e.difficulte})`).join(' | ');
const listeExercicesNoms = exercices.map(e => e.nom).join(', ');

return {
  json: {
    ...user,
    liste_exercices_dispo: listeExercicesNoms,
    liste_exercices_details: listeExercicesDetails,
    calc_calories:  Math.round(calObj),
    calc_proteines: Math.round(user.poids * (user.objectif.includes('Restructuration') ? 2.2 : 2)),
    calc_lipides:   Math.round(user.poids * 0.9),
    calc_glucides:  Math.round((calObj - (user.poids * 2 * 4) - (user.poids * 0.9 * 9)) / 4),
    jour_semaine:   jourSemaine,
    num_semaine:    numSemaine,
    phase_hebdo:    phaseHebdo,
    split_selectionne: splitSelectionne,
    exercices_list: exercices
  }
};

// --- Récupération des données
const user = $('Récup Infos Utilisateur').first().json;
const exercices = $('Récup Liste Exercices').all().map(e => e.json);

// --- Vérification des données
if (!user.age || !user.poids || !user.taille || !user.jours_disponibilite || !user.date_fin) {
  throw new Error('Données utilisateur incomplètes');
}

// --- Normalisation des champs texte
const niveau = (user.niveau || 'Débutant').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const objectif = user.objectif;
const materiel = (user.materiel || 'Rien').toLowerCase();

// --- Calcul des macros
let bmr = (user.sexe === 'Homme')
  ? (10 * user.poids) + (6.25 * user.taille) - (5 * user.age) + 5
  : (10 * user.poids) + (6.25 * user.taille) - (5 * user.age) - 161;
let tdee = bmr * 1.4;
let calObj = tdee;
switch (objectif) {
  case 'Perte de poids':             calObj = tdee * 0.80; break;
  case 'Prise de masse':             calObj = tdee * 1.15; break;
  case 'Restructuration corporelle': calObj = tdee * 0.95; break;
  default:                           calObj = tdee; break;
}

// --- Données temporelles
const now = new Date();
const jourSemaine = now.getDay();
const debutAnnee = new Date(now.getFullYear(), 0, 1);
const numSemaine = Math.ceil(((now - debutAnnee) / 86400000 + debutAnnee.getDay() + 1) / 7);
const phases = ['montee', 'pic', 'decharge'];
const phaseHebdo = phases[numSemaine % 3];

// --- Analyse des jours disponibles
const DAY_NAMES_FR = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];
const DAY_INDEX = {};
DAY_NAMES_FR.forEach((d, i) => { DAY_INDEX[d] = i; });

const joursDispoStr = user.jours_disponibilite.split(',').map(j => j.trim());
const joursDispoIndex = joursDispoStr.map(j => DAY_INDEX[j]).filter(i => i !== undefined);
const nbJours = joursDispoIndex.length;

// Détection des jours consécutifs
let consecutifMax = 1;
let current = 1;
for (let i = 1; i < joursDispoIndex.length; i++) {
  if (joursDispoIndex[i] === joursDispoIndex[i-1] + 1 ||
      (joursDispoIndex[i-1] === 6 && joursDispoIndex[i] === 0)) {
    current++;
    consecutifMax = Math.max(consecutifMax, current);
  } else {
    current = 1;
  }
}

// --- Sélection du split intelligent
let splitSelectionne;
let sessionTypesCycle = [];

if (nbJours <= 2) {
  splitSelectionne = 'Full Body';
  sessionTypesCycle = ['fullbody'];
} else if (nbJours === 3) {
  if (niveau === 'debutant' || consecutifMax >= 3) {
    splitSelectionne = 'Full Body';
    sessionTypesCycle = ['fullbody'];
  } else {
    splitSelectionne = 'Push / Pull / Legs';
    sessionTypesCycle = ['push', 'pull', 'legs'];
  }
} else if (nbJours === 4) {
  splitSelectionne = 'Upper / Lower';
  sessionTypesCycle = ['upper', 'lower', 'upper', 'lower'];
} else { // 5 ou 6 jours
  if (consecutifMax > 3 && niveau !== 'avance') {
    splitSelectionne = 'Full Body (adapté)';
    sessionTypesCycle = ['fullbody'];
  } else {
    splitSelectionne = 'PPL 6 jours';
    sessionTypesCycle = ['push', 'pull', 'legs', 'push', 'pull', 'legs'];
  }
}

// --- Nombre d'exercices selon split et niveau
const NB_EXERCICES = {
  fullbody: niveau === 'debutant' ? 5 : 6,
  push:     niveau === 'debutant' ? 4 : 5,
  pull:     niveau === 'debutant' ? 4 : 5,
  legs:     niveau === 'debutant' ? 4 : 5,
  upper:    niveau === 'debutant' ? 5 : 6,
  lower:    niveau === 'debutant' ? 4 : 5
};

// --- Séries / répétitions
let series, reps;
switch (objectif) {
  case 'Prise de masse':
    series = niveau === 'debutant' ? 3 : 4;
    reps   = niveau === 'debutant' ? 8 : 6;
    break;
  case 'Perte de poids':
    series = niveau === 'debutant' ? 3 : 4;
    reps   = 15;
    break;
  default:
    series = niveau === 'debutant' ? 3 : 4;
    reps   = 12;
}

let reposSecondes;
switch (objectif) {
  case 'Prise de masse':             reposSecondes = 180; break;
  case 'Restructuration corporelle': reposSecondes = 90;  break;
  case 'Perte de poids':             reposSecondes = 45;  break;
  default:                           reposSecondes = 60;
}
if (niveau === 'debutant') reposSecondes += 30;

// --- Périodisation hebdomadaire
if (phaseHebdo === 'montee') {
  series = Math.min(series + 1, 5);
  reps   = Math.max(reps - 2, 5);
} else if (phaseHebdo === 'decharge') {
  series = Math.max(series - 1, 2);
  reps   = Math.min(reps + 3, 20);
  reposSecondes = Math.round(reposSecondes * 0.75);
}

// --- Dates de planification (max 30 jours)
const dateFin = new Date(user.date_fin);
const today = new Date();
today.setHours(0,0,0,0);
const maxDays = 30;
const limitDate = new Date(today);
limitDate.setDate(today.getDate() + maxDays);
const endDate = dateFin < limitDate ? dateFin : limitDate;

// Fonction d'ajustement par semaine
function adjustByWeek(date, baseSeries, baseReps) {
  const diffDays = Math.floor((date - today) / (1000 * 3600 * 24));
  const weekNum = Math.floor(diffDays / 7) + 1;
  let seriesAdj = baseSeries, repsAdj = baseReps;
  if (weekNum === 2) seriesAdj = Math.min(baseSeries + 1, 5);
  else if (weekNum === 3) repsAdj = Math.min(baseReps + 2, 20);
  else if (weekNum === 4) { seriesAdj = Math.min(baseSeries + 1, 5); repsAdj = Math.min(baseReps + 2, 20); }
  return { series: seriesAdj, reps: repsAdj };
}

// --- Génération des dates
const datesToSchedule = [];
let currentDate = new Date(today);
while (currentDate <= endDate) {
  if (joursDispoIndex.includes(currentDate.getDay())) {
    datesToSchedule.push(new Date(currentDate));
  }
  currentDate.setDate(currentDate.getDate() + 1);
}

// --- Assignation des types de séances
let assignedSessionTypes;
if (sessionTypesCycle.length === 1) {
  assignedSessionTypes = datesToSchedule.map(() => sessionTypesCycle[0]);
} else {
  assignedSessionTypes = datesToSchedule.map((_, idx) => sessionTypesCycle[idx % sessionTypesCycle.length]);
}

// --- Filtrage des exercices
function matchMateriel(exo) {
  const cat = (exo.categorie || '').toLowerCase();
  if (materiel === 'rien') {
    // Seuls les exercices sans équipement : Gainage, Abdominaux, Cardio
    return ['gainage', 'abdominaux', 'cardio'].includes(cat);
  }
  if (materiel === 'haltères') {
    const nom = (exo.nom || '').toLowerCase();
    return !nom.includes('barre') && !nom.includes('machine') && !nom.includes('poulie');
  }
  return true; // 'salle complète' ou autre
}

let filteredExercises = exercices;
if (niveau === 'debutant') {
  filteredExercises = filteredExercises.filter(e => e.difficulte !== 'Avancé');
}
if (objectif !== 'Prise de masse') {
  filteredExercises = filteredExercises.filter(e => e.difficulte !== 'Avancé');
}
filteredExercises = filteredExercises.filter(matchMateriel);

// --- Sélection des exercices par type
function getExercisesByType(sessionType) {
  let filtered = [];
  switch (sessionType) {
    case 'fullbody':
      filtered = filteredExercises.filter(e => e.categorie === 'Musculation' || e.categorie === 'Gainage' || e.categorie === 'Abdominaux');
      break;
    case 'push':
      filtered = filteredExercises.filter(e => e.muscles && (e.muscles.includes('Pectoraux') || e.muscles.includes('Triceps') || e.muscles.includes('Épaules')));
      break;
    case 'pull':
      filtered = filteredExercises.filter(e => e.muscles && (e.muscles.includes('Dos') || e.muscles.includes('Biceps')));
      break;
    case 'legs':
      filtered = filteredExercises.filter(e => e.muscles && (e.muscles.includes('Quadriceps') || e.muscles.includes('Fessiers') || e.muscles.includes('Ischio')));
      break;
    case 'upper':
      filtered = filteredExercises.filter(e => e.muscles && (e.muscles.includes('Pectoraux') || e.muscles.includes('Dos') || e.muscles.includes('Épaules') || e.muscles.includes('Biceps') || e.muscles.includes('Triceps')));
      break;
    case 'lower':
      filtered = filteredExercises.filter(e => e.muscles && (e.muscles.includes('Quadriceps') || e.muscles.includes('Fessiers') || e.muscles.includes('Ischio') || e.muscles.includes('Mollets')));
      break;
    default: filtered = [];
  }
  return filtered.sort(() => 0.5 - Math.random());
}

const exerciseLists = {};
const typesNeeded = [...new Set(assignedSessionTypes)];
for (const type of typesNeeded) {
  exerciseLists[type] = getExercisesByType(type);
}

const pointers = {};
for (const type of typesNeeded) {
  pointers[type] = 0;
}

function selectExercises(sessionType) {
  const list = exerciseLists[sessionType];
  if (!list || list.length === 0) return [];
  const limit = NB_EXERCICES[sessionType] || 4;
  const selected = [];
  let pointer = pointers[sessionType];
  for (let i = 0; i < limit; i++) {
    selected.push(list[pointer % list.length]);
    pointer++;
  }
  pointers[sessionType] = pointer % list.length;
  return selected;
}

// --- Construction des séances et du résumé détaillé
const seances = [];
const summarySeances = []; // Pour affichage dans le résumé

for (let i = 0; i < datesToSchedule.length; i++) {
  const date = datesToSchedule[i];
  const type = assignedSessionTypes[i];
  const { series: weekSeries, reps: weekReps } = adjustByWeek(date, series, reps);
  const selectedExos = selectExercises(type);
  if (selectedExos.length === 0) continue;

  const jour = DAY_NAMES_FR[date.getDay()];
  const exosDetails = selectedExos.map(exo => ({
    nom: exo.nom,
    muscles: exo.muscles,
    series: weekSeries,
    repetitions: weekReps,
    repos: reposSecondes
  }));

  summarySeances.push({
    date: date.toISOString().slice(0,10),
    jour: jour,
    type: type,
    exercices: exosDetails
  });

  for (const exo of selectedExos) {
    seances.push({
      utilisateur_id:  user.id,
      exercice_id:     exo.id,
      date_programmee: date.toISOString().slice(0,10),
      series:          weekSeries,
      repetitions:     weekReps,
      repos_secondes:  reposSecondes
    });
  }
}

// --- Recommandations nutritionnelles
const dailyCals = Math.round(calObj);
const dailyProt = Math.round(user.poids * (objectif.includes('Restructuration') ? 2.2 : 2));
const dailyGluc = Math.round((dailyCals - (dailyProt * 4) - (Math.round(user.poids * 0.9) * 9)) / 4);
const dailyLip  = Math.round(user.poids * 0.9);

function makeMeal(mealName, type, percent) {
  return {
    utilisateur_id: user.id,
    titre:          mealName,
    description:    `Repas ${mealName} personnalisé pour ${user.pseudo}. Ajustez les portions pour atteindre vos objectifs.`,
    type_repas:     type,
    calories:       Math.round(dailyCals * percent),
    proteines:      Math.round(dailyProt * percent),
    glucides:       Math.round(dailyGluc * percent),
    lipides:        Math.round(dailyLip  * percent)
  };
}
const recommandations = [
  makeMeal('Petit-déjeuner', 'petit_dejeuner', 0.25),
  makeMeal('Déjeuner',       'dejeuner',       0.35),
  makeMeal('Dîner',          'diner',          0.30),
  makeMeal('Collation',      'collation',      0.10)
];

// --- Batching SQL
function chunkArray(array, size) {
  const chunks = [];
  for (let i = 0; i < array.length; i += size) chunks.push(array.slice(i, i + size));
  return chunks;
}
const BATCH_SIZE = 100;
const seanceBatches = chunkArray(seances, BATCH_SIZE);
const insertSeancesBatches = seanceBatches.map(batch => {
  const values = batch.map(s => `(${s.utilisateur_id}, ${s.exercice_id}, '${s.date_programmee}', ${s.series}, ${s.repetitions}, ${s.repos_secondes})`).join(',\n');
  return { query: `INSERT INTO fittracker.seances (utilisateur_id, exercice_id, date_programmee, series, repetitions, repos_secondes) VALUES\n${values}` };
});

let insertRecommandationsQuery = '';
if (recommandations.length) {
  const values = recommandations.map(r => `(${r.utilisateur_id}, '${r.titre.replace(/'/g, "\\'")}', '${r.description.replace(/'/g, "\\'")}', '${r.type_repas}', ${r.calories}, ${r.proteines}, ${r.glucides}, ${r.lipides})`).join(',\n');
  insertRecommandationsQuery = `INSERT INTO fittracker.recommandations_nutrition (utilisateur_id, titre, description, type_repas, calories, proteines, glucides, lipides) VALUES\n${values}`;
}

// --- Construction du résumé complet
const programmeSummary = {
  utilisateur: user.pseudo,
  split: splitSelectionne,
  nb_jours: nbJours,
  jours: joursDispoStr.join(', '),
  niveau: user.niveau,
  objectif: objectif,
  phase_hebdo: phaseHebdo,
  periode: {
    debut: today.toISOString().slice(0,10),
    fin: endDate.toISOString().slice(0,10),
    nb_seances_prevues: datesToSchedule.length
  },
  parametres_entrainement: {
    series_base: series,
    repetitions_base: reps,
    repos_secondes: reposSecondes,
    progression: "ajustement hebdomadaire (surcharge progressive)"
  },
  details_seances: summarySeances,
  recommandations_nutrition: recommandations.map(r => `${r.titre} : ${r.calories} kcal, ${r.proteines}g P, ${r.glucides}g G, ${r.lipides}g L`),
  conseils: [
    "Échauffement : 10 minutes de cardio léger + mobilité articulaire avant chaque séance.",
    "Hydratation : au moins 1,5L d'eau par jour, plus pendant l'effort.",
    "Respectez les temps de repos pour optimiser la récupération.",
    "Pour progresser, essayez d'augmenter la charge ou les répétitions chaque semaine (surcharge progressive).",
    "En cas de douleur, adaptez ou consultez un professionnel."
  ]
};

// --- Retour des trois actions avec le résumé attaché à la première
return [
  { json: { action: 'update_macros', utilisateur_id: user.id, calories: dailyCals, proteines: dailyProt, glucides: dailyGluc, lipides: dailyLip, summary: programmeSummary } },
  { json: { action: 'insert_seances', seances: seances, insertSeancesBatches: insertSeancesBatches, utilisateur_id: user.id, startDate: today.toISOString().slice(0,10), endDate: endDate.toISOString().slice(0,10) } },
  { json: { action: 'insert_recommandations', recommandations: recommandations, insertRecommandationsQuery: insertRecommandationsQuery } }
];

const data = $('Switch — Router Actions').item.json;
const batches = data.insertSeancesBatches;
if (!batches || batches.length === 0) {
  return [{ json: { query: 'SELECT 1' } }];
}
return batches.map(batch => ({ json: { query: batch.query } }));

const data = $input.first().json;
const summary = data.summary;
const utilisateur_id = data.utilisateur_id;
const calories = data.calories;
const proteines = data.proteines;
const glucides = data.glucides;
const lipides = data.lipides;

// On exécute la requête SQL via un nœud MySQL séparé, mais ici on renvoie simplement les données
// pour que le nœud suivant (MySQL) les utilise.
return [
  {
    json: {
      query: `UPDATE fittracker.utilisateurs SET calories_objectif = ${calories}, proteines_objectif = ${proteines}, glucides_objectif = ${glucides}, lipides_objectif = ${lipides}, modifie_le = NOW() WHERE id = ${utilisateur_id}`,
      summary: summary
    }
  }
];
